insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M72602','listening',1,1,'judge','夏天如果没有出汗，不用洗澡。',null,'×','auto',1,'/mock-tests/m72602/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Буруу (×). Эхний өгүүлбэрт «即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡» гэсэн: илт хөлрөөгүй ч зун өдөр бүр усанд орохыг зөвлөдөг. Тиймээс «хөлрөөгүй бол усанд орох шаардлагагүй» гэдэг нь эсрэг утгатай.',86.91,289.26,'夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。
我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。
研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。
此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。','{"transcript": [{"zh": "夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。", "mn": "Зуны улиралд хөлөрсөн бол усанд ордог нь хүн бүрийн мэддэг энгийн ойлголт. Харин өнөөдөр хөлрөөгүй бол усанд орох хэрэгтэй юу? Хариултыг түрүүлж хэлье: илт хөлрөөгүй ч гэсэн зуны улиралд өдөр бүр нэг удаа усанд орвол хамгийн сайн гэж бид зөвлөдөг."}, {"zh": "我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。", "mn": "Бидний арьсны гадаргуу хөлс булчирхайгаар бараг дүүрэн бөгөөд тэдгээр нь 2–4 сая орчим байдаг. Алга, улыг жишээ авбал нэг дөрвөлжин см арьсанд 250–550 хөлс булчирхай бий. Бид дасгал хийх, халуун орчинд байх, сэтгэл хөдлөх үед арьсны хөлс булчирхай хөлс ялгаруулж, ууршилтаар дулаан гаргаж, биеийн температурыг зохицуулан, бие хэт халахаас сэргийлдэг. Энэ үеийн хөлсийг хүн бүр илт мэдэрнэ. Гэтэл үнэндээ хөлрөлтөө мэдэрдэггүй байсан ч бид хором тутам хөлөрсөөр байдаг. Мэдрэгддэггүй ийм хөлрөлтийг «үл мэдэгдэх хөлрөлт» гэнэ."}, {"zh": "研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。", "mn": "Судалгаагаар орчны температур 22, 27, 30 °C байх үед амарч буй эрүүл насанд хүрсэн эрэгтэй өдөрт үл мэдэгдэх хөлрөлтөөр нийт 381, 526, 695 мл хөлс гаргадаг байна. Өөрөөр хэлбэл хүн юу ч хийгээгүй байхад арьс нь өдөр бүр чимээгүйхэн нэг сав ундаатай ойролцоо хэмжээний хөлс гаргадаг."}, {"zh": "此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。", "mn": "Түүнчлэн, хөлс бага гарсан ч арьс орчны тоос шороотой харьцсаар байдаг, арьс өөрөө тос ялгаруулдаг бөгөөд эдгээр нь арьсны гадаргуу дээр хуримтлагддагийг анхаарах хэрэгтэй. Иймээс илт хөлрөөгүй ч зохистой давтамжтай усанд орж, биеэ цэвэр байлгахыг зөвлөдөг."}], "key": "即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡", "keyMn": "Илт хөлрөөгүй ч зун өдөр бүр нэг удаа усанд орвол хамгийн сайн", "why": "Буруу (×). Эхний өгүүлбэрт «即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡» гэсэн: илт хөлрөөгүй ч зун өдөр бүр усанд орохыг зөвлөдөг. Тиймээс «хөлрөөгүй бол усанд орох шаардлагагүй» гэдэг нь эсрэг утгатай.", "tip": "Эхний өгүүлбэрт «先说答案» гэж хариултаа шууд хэлдэг. Ийм үг гарвал түүнд анхаар.", "words": [{"zh": "出汗", "pinyin": "chūhàn", "mn": "хөлрөх"}, {"zh": "洗澡", "pinyin": "xǐzǎo", "mn": "усанд орох"}, {"zh": "不显性出汗", "pinyin": "bù xiǎnxìng chūhàn", "mn": "үл мэдэгдэх хөлрөлт"}, {"zh": "汗腺", "pinyin": "hànxiàn", "mn": "хөлс булчирхай"}, {"zh": "油脂", "pinyin": "yóuzhī", "mn": "арьсны тос"}]}'::jsonb),
('M72602','listening',1,2,'judge','以手掌和脚掌为例，每平方厘米的皮肤有250到550个汗腺。',null,'√','auto',1,'/mock-tests/m72602/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Зөв (√). Хоёр дахь догол мөрт «以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺» гэж яг ингэж хэлсэн. Тоо нь ижил байна.',86.91,289.26,'夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。
我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。
研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。
此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。','{"transcript": [{"zh": "夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。", "mn": "Зуны улиралд хөлөрсөн бол усанд ордог нь хүн бүрийн мэддэг энгийн ойлголт. Харин өнөөдөр хөлрөөгүй бол усанд орох хэрэгтэй юу? Хариултыг түрүүлж хэлье: илт хөлрөөгүй ч гэсэн зуны улиралд өдөр бүр нэг удаа усанд орвол хамгийн сайн гэж бид зөвлөдөг."}, {"zh": "我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。", "mn": "Бидний арьсны гадаргуу хөлс булчирхайгаар бараг дүүрэн бөгөөд тэдгээр нь 2–4 сая орчим байдаг. Алга, улыг жишээ авбал нэг дөрвөлжин см арьсанд 250–550 хөлс булчирхай бий. Бид дасгал хийх, халуун орчинд байх, сэтгэл хөдлөх үед арьсны хөлс булчирхай хөлс ялгаруулж, ууршилтаар дулаан гаргаж, биеийн температурыг зохицуулан, бие хэт халахаас сэргийлдэг. Энэ үеийн хөлсийг хүн бүр илт мэдэрнэ. Гэтэл үнэндээ хөлрөлтөө мэдэрдэггүй байсан ч бид хором тутам хөлөрсөөр байдаг. Мэдрэгддэггүй ийм хөлрөлтийг «үл мэдэгдэх хөлрөлт» гэнэ."}, {"zh": "研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。", "mn": "Судалгаагаар орчны температур 22, 27, 30 °C байх үед амарч буй эрүүл насанд хүрсэн эрэгтэй өдөрт үл мэдэгдэх хөлрөлтөөр нийт 381, 526, 695 мл хөлс гаргадаг байна. Өөрөөр хэлбэл хүн юу ч хийгээгүй байхад арьс нь өдөр бүр чимээгүйхэн нэг сав ундаатай ойролцоо хэмжээний хөлс гаргадаг."}, {"zh": "此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。", "mn": "Түүнчлэн, хөлс бага гарсан ч арьс орчны тоос шороотой харьцсаар байдаг, арьс өөрөө тос ялгаруулдаг бөгөөд эдгээр нь арьсны гадаргуу дээр хуримтлагддагийг анхаарах хэрэгтэй. Иймээс илт хөлрөөгүй ч зохистой давтамжтай усанд орж, биеэ цэвэр байлгахыг зөвлөдөг."}], "key": "以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺", "keyMn": "Алга, улыг жишээ авбал нэг дөрвөлжин см арьсанд 250–550 хөлс булчирхай бий", "why": "Зөв (√). Хоёр дахь догол мөрт «以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺» гэж яг ингэж хэлсэн. Тоо нь ижил байна.", "tip": "Тоон мэдээлэлтэй √/× асуултад тоог бүрэн тулган шалга.", "words": [{"zh": "手掌", "pinyin": "shǒuzhǎng", "mn": "алга"}, {"zh": "脚掌", "pinyin": "jiǎozhǎng", "mn": "тавхай, улны хэсэг"}, {"zh": "平方厘米", "pinyin": "píngfāng límǐ", "mn": "дөрвөлжин сантиметр"}, {"zh": "汗腺", "pinyin": "hànxiàn", "mn": "хөлс булчирхай"}]}'::jsonb),
('M72602','listening',1,3,'judge','我们每时每刻都在出汗。',null,'√','auto',1,'/mock-tests/m72602/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Зөв (√). «即使感觉不到在出汗，我们也无时无刻不在出汗» гэсэн: хөлрөлтөө мэдэрдэггүй ч бид хором тутам хөлөрсөөр байдаг. Энэ бол «үл мэдэгдэх хөлрөлт».',86.91,289.26,'夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。
我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。
研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。
此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。','{"transcript": [{"zh": "夏天出汗了要洗澡，这是大家的基本共识。那如果今天没有出汗，还要不要洗澡呢？先说答案：即使没有明显出汗，我们也建议夏天最好可以每天洗一次澡。", "mn": "Зуны улиралд хөлөрсөн бол усанд ордог нь хүн бүрийн мэддэг энгийн ойлголт. Харин өнөөдөр хөлрөөгүй бол усанд орох хэрэгтэй юу? Хариултыг түрүүлж хэлье: илт хөлрөөгүй ч гэсэн зуны улиралд өдөр бүр нэг удаа усанд орвол хамгийн сайн гэж бид зөвлөдөг."}, {"zh": "我们的皮肤表面几乎布满了汗腺，多达200万—400万个。以手掌和脚掌为例，每平方厘米的皮肤就有250到550个汗腺。当我们在运动、处于高温环境或情绪激动时，皮肤的汗腺就会分泌汗水，通过蒸发散热调节体温，避免身体过热。这时候的汗，大家能明显感觉到。但其实，即使感觉不到在出汗，我们也无时无刻不在出汗。这种没有感觉到的出汗，就是“不显性出汗”。", "mn": "Бидний арьсны гадаргуу хөлс булчирхайгаар бараг дүүрэн бөгөөд тэдгээр нь 2–4 сая орчим байдаг. Алга, улыг жишээ авбал нэг дөрвөлжин см арьсанд 250–550 хөлс булчирхай бий. Бид дасгал хийх, халуун орчинд байх, сэтгэл хөдлөх үед арьсны хөлс булчирхай хөлс ялгаруулж, ууршилтаар дулаан гаргаж, биеийн температурыг зохицуулан, бие хэт халахаас сэргийлдэг. Энэ үеийн хөлсийг хүн бүр илт мэдэрнэ. Гэтэл үнэндээ хөлрөлтөө мэдэрдэггүй байсан ч бид хором тутам хөлөрсөөр байдаг. Мэдрэгддэггүй ийм хөлрөлтийг «үл мэдэгдэх хөлрөлт» гэнэ."}, {"zh": "研究发现，在环境温度分别为22 ℃、27 ℃和30 ℃的时候，正常成年男性在休息状态下，每天不显性出汗的总量分别是381毫升、526毫升和695毫升。也就是说，人什么都没做，每天皮肤都会悄悄地排出差不多一瓶饮料那么多的汗水。", "mn": "Судалгаагаар орчны температур 22, 27, 30 °C байх үед амарч буй эрүүл насанд хүрсэн эрэгтэй өдөрт үл мэдэгдэх хөлрөлтөөр нийт 381, 526, 695 мл хөлс гаргадаг байна. Өөрөөр хэлбэл хүн юу ч хийгээгүй байхад арьс нь өдөр бүр чимээгүйхэн нэг сав ундаатай ойролцоо хэмжээний хөлс гаргадаг."}, {"zh": "此外，要注意的是，即使出汗不多，皮肤仍然会接触到环境中的灰尘，皮肤还会自然分泌油脂，这些都会在皮肤表面堆积。所以说，即使没有明显出汗，建议也要保持适度的洗澡频率，保持身体清洁。", "mn": "Түүнчлэн, хөлс бага гарсан ч арьс орчны тоос шороотой харьцсаар байдаг, арьс өөрөө тос ялгаруулдаг бөгөөд эдгээр нь арьсны гадаргуу дээр хуримтлагддагийг анхаарах хэрэгтэй. Иймээс илт хөлрөөгүй ч зохистой давтамжтай усанд орж, биеэ цэвэр байлгахыг зөвлөдөг."}], "key": "我们也无时无刻不在出汗", "keyMn": "Бид хором тутам хөлөрсөөр байдаг", "why": "Зөв (√). «即使感觉不到在出汗，我们也无时无刻不在出汗» гэсэн: хөлрөлтөө мэдэрдэггүй ч бид хором тутам хөлөрсөөр байдаг. Энэ бол «үл мэдэгдэх хөлрөлт».", "words": [{"zh": "无时无刻", "pinyin": "wú shí wú kè", "mn": "хором тутам, үргэлж"}, {"zh": "感觉", "pinyin": "gǎnjué", "mn": "мэдрэх"}, {"zh": "蒸发", "pinyin": "zhēngfā", "mn": "ууршилт"}, {"zh": "散热", "pinyin": "sànrè", "mn": "дулаан гаргах"}]}'::jsonb),
